/* global Office */

const MESSAGE_DISPLAY_DURATION = 5000;

const REQUIRED_ATTENDEES = [
    'uko.a.naito@rakuten.com',
    'risako.homma@rakuten.com',
    'hikari.wakaki@rakuten.com',
    'karin.yoshimura@rakuten.com'
];

// 月名→月番号マッピング（略称・正式名称両対応）
const MONTH_MAP = {
    'JAN': 1, 'JANUARY': 1,
    'FEB': 2, 'FEBRUARY': 2,
    'MAR': 3, 'MARCH': 3,
    'APR': 4, 'APRIL': 4,
    'MAY': 5,
    'JUN': 6, 'JUNE': 6,
    'JUL': 7, 'JULY': 7,
    'AUG': 8, 'AUGUST': 8,
    'SEP': 9, 'SEPTEMBER': 9,
    'OCT': 10, 'OCTOBER': 10,
    'NOV': 11, 'NOVEMBER': 11,
    'DEC': 12, 'DECEMBER': 12
};

Office.onReady(function(info) {
    if (info.host === Office.HostType.Outlook) {
        document.getElementById('create-event-button').onclick = createEventFromEmail;
    }
});

async function createEventFromEmail() {
    setMessage('処理中...', 'black');

    try {
        const item = Office.context.mailbox.item;

        if (!item || item.itemType !== Office.MailboxEnums.ItemType.Message) {
            setMessage('エラー: メールが選択されていません。', 'red');
            return;
        }

        // 件名に "Disney Travel Trade Connectivity (TTC)" が含まれているか確認
        const subject = item.subject || '';
        if (!subject.includes('Disney Travel Trade Connectivity (TTC)')) {
            setMessage('エラー: Disney TTC Planned Outage / Maintenance通知メールではありません。', 'red');
            return;
        }

        // 本文からStart/End日時を抽出
        const { startJST, endJST } = await extractOutageTimes(item);

        if (!startJST || !endJST) {
            setMessage('エラー: Outage Window Timesの取得に失敗しました。', 'red');
            return;
        }

        // イベント件名（JST時刻をHH:MM形式で）
        const startTimeStr = formatTime(startJST);
        const endTimeStr = formatTime(endJST);
        const eventSubject = `【Disney】Planned Outage ${startTimeStr} - ${endTimeStr}`;

        // 本文生成
        const bodyContent = createEventBody(startJST, endJST);

        Office.context.mailbox.displayNewAppointmentForm({
            requiredAttendees: REQUIRED_ATTENDEES,
            subject: eventSubject,
            start: startJST,
            end: endJST,
            body: bodyContent,
            location: '',
        });

        setMessage('イベント作成フォームを開きました。', 'green');

    } catch (error) {
        setMessage(`エラーが発生しました: ${error.message}`, 'red');
        console.error(error);
    }
}

/**
 * メール本文からOutage Window TimesのStart/EndをJSTのDateオブジェクトとして返す
 */
async function extractOutageTimes(item) {
    return new Promise((resolve) => {
        item.body.getAsync(Office.CoercionType.Text, (asyncResult) => {
            if (asyncResult.status !== Office.AsyncResultStatus.Succeeded) {
                resolve({ startJST: null, endJST: null });
                return;
            }

            // 本文を正規化（ノーブレークスペース・全角スペース等を通常スペースに統一）
            const raw = asyncResult.value;
            const text = raw.replace(/[ 　\t]/g, ' ');

            // Start: と End: の後ろの日時を取得
            const startMatch = extractDateTimeAfterLabel(text, 'Start');
            const endMatch = extractDateTimeAfterLabel(text, 'End');

            if (!startMatch || !endMatch) {
                resolve({ startJST: null, endJST: null });
                return;
            }

            const startJST = convertETtoJST(startMatch);
            const endJST = convertETtoJST(endMatch);

            resolve({ startJST, endJST });
        });
    });
}

/**
 * テキストから "Start:" または "End:" の後の日時文字列を解析する
 * 例: "Start:  4th-MAR-2026 00:30AM ET"
 */
function extractDateTimeAfterLabel(text, label) {
    // 対応フォーマット例：
    //   Start:  4th-MAR-2026 00:30AM ET
    //   Start: 2nd-JUL-2026 2:00 AM - ET
    //   Start: 14th-JUNE-2026 11:30 PM-ET
    //   Start:  17th-JUNE-2026 11:00 PM-ET
    const pattern = new RegExp(
        label + '[:\\s]+' +
        '(\\d{1,2})(?:st|nd|rd|th)[\\s\\-]+([A-Za-z]{3,9})[\\s\\-]+(\\d{4})' +
        '[\\s,]+' +
        '(\\d{1,2}:\\d{2})[\\s]*(AM|PM)[\\s\\-]*(E[DS]?T)',
        'i'
    );
    const m = text.match(pattern);
    if (!m) return null;

    const monthKey = m[2].toUpperCase();
    const month = MONTH_MAP[monthKey];
    if (!month) return null;

    return {
        day: parseInt(m[1], 10),
        month: month,
        year: parseInt(m[3], 10),
        time: m[4],
        ampm: m[5].toUpperCase(),
        tz: m[6].toUpperCase()
    };
}

/**
 * 指定した年・月・日がEDT（サマータイム）期間内かどうかを返す
 * EDT期間：3月第2日曜日 02:00 〜 11月第1日曜日 02:00（米国東部時間）
 */
function isEDT(year, month, day) {
    // 3月の第2日曜日を求める
    const marchSecondSunday = getNthSunday(year, 3, 2);
    // 11月の第1日曜日を求める
    const novFirstSunday = getNthSunday(year, 11, 1);

    const date = new Date(year, month - 1, day);
    const dstStart = new Date(year, 2, marchSecondSunday); // 3月（0始まりで2）
    const dstEnd = new Date(year, 10, novFirstSunday);     // 11月（0始まりで10）

    return date >= dstStart && date < dstEnd;
}

/**
 * 指定した年・月のN番目の日曜日の日付（日）を返す
 */
function getNthSunday(year, month, n) {
    const first = new Date(year, month - 1, 1);
    const firstSundayOffset = (7 - first.getDay()) % 7;
    return 1 + firstSundayOffset + (n - 1) * 7;
}

/**
 * ET（Eastern Time）のパース結果をJSTのDateオブジェクトに変換する
 * メールが EDT/EST を明示しない場合は日付から自動判定する
 * EST = UTC-5, EDT = UTC-4
 * JST = UTC+9
 */
function convertETtoJST(parsed) {
    if (!parsed) return null;

    const [hourStr, minStr] = parsed.time.split(':');
    let hour = parseInt(hourStr, 10);
    const min = parseInt(minStr, 10);

    // 12時間表記を24時間に変換
    if (parsed.ampm === 'AM') {
        if (hour === 12) hour = 0;
    } else {
        if (hour !== 12) hour += 12;
    }

    // EDT明示 → UTC-4、EST明示 → UTC-5、ET のみ → 日付から自動判定
    let etOffsetHours;
    if (parsed.tz === 'EDT') {
        etOffsetHours = -4;
    } else if (parsed.tz === 'EST') {
        etOffsetHours = -5;
    } else {
        etOffsetHours = isEDT(parsed.year, parsed.month, parsed.day) ? -4 : -5;
    }

    // UTC時刻を計算
    const utcDate = new Date(Date.UTC(
        parsed.year,
        parsed.month - 1,
        parsed.day,
        hour - etOffsetHours,
        min
    ));

    // JSTのYYYY, MM, DD, HH, mm を求める（UTC+9）
    const jstOffsetMs = 9 * 60 * 60 * 1000;
    const jstMs = utcDate.getTime() + jstOffsetMs;
    const jstDate = new Date(jstMs);

    return new Date(
        jstDate.getUTCFullYear(),
        jstDate.getUTCMonth(),
        jstDate.getUTCDate(),
        jstDate.getUTCHours(),
        jstDate.getUTCMinutes()
    );
}

/**
 * HH:MM 形式の文字列を返す
 */
function formatTime(date) {
    const h = String(date.getHours()).padStart(2, '0');
    const m = String(date.getMinutes()).padStart(2, '0');
    return `${h}:${m}`;
}

/**
 * YYYY年MM月DD日 形式の文字列を返す
 */
function formatDate(date) {
    const y = date.getFullYear();
    const mo = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}年${mo}月${d}日`;
}

/**
 * Start時刻の5分前のDateオブジェクトを返す
 */
function fiveMinsBefore(date) {
    return new Date(date.getTime() - 5 * 60 * 1000);
}

/**
 * カレンダーイベントの本文（HTML）を作成する
 */
